def solve():
    with open('/workdir/data/parking.txt', 'r') as f:
        content = f.read()
    lines = content.splitlines()

    first_line = lines[0].split()
    n = int(first_line[0])
    m = int(first_line[1])

    grid = []
    for i in range(1, n + 1):
        grid.append(list(lines[i]))

    # Compute down[r][c]: number of consecutive '.' starting from (r,c) going down (inclusive)
    down = [[0] * m for _ in range(n)]
    for c in range(m):
        curr = 0
        for r in range(n - 1, -1, -1):
            if grid[r][c] == '.':
                curr += 1
                down[r][c] = curr
            else:
                curr = 0
                down[r][c] = 0

    # Compute right[r][c]: number of consecutive '.' starting from (r,c) going right (inclusive)
    right = [[0] * m for _ in range(n)]
    for r in range(n):
        curr = 0
        for c in range(m - 1, -1, -1):
            if grid[r][c] == '.':
                curr += 1
                right[r][c] = curr
            else:
                curr = 0
                right[r][c] = 0

    # diff array for 2D range updates
    # Size (n+2) x (m+2) to handle indices up to n+1 and m+1
    diff = [[0] * (m + 2) for _ in range(n + 2)]

    for r in range(n):
        for c in range(m):
            if grid[r][c] == '.':
                h_max = down[r][c]
                w_max = right[r][c]
                # Update rectangle [1, h_max] x [1, w_max]
                diff[1][1] += 1
                diff[1][w_max + 1] -= 1
                diff[h_max + 1][1] -= 1
                diff[h_max + 1][w_max + 1] += 1

    # Compute 2D prefix sums to get actual counts
    # After this, diff[i][j] will contain the count for tent size i x j
    # We iterate through all cells and accumulate
    # First do horizontal accumulation, then vertical
    for r in range(1, n + 2):
        for c in range(1, m + 2):
            diff[r][c] += diff[r][c-1]  # accumulate from left
    for r in range(1, n + 2):
        for c in range(1, m + 2):
            diff[r][c] += diff[r-1][c]  # accumulate from top

    # Now diff[i][j] contains count for tent size i x j
    # Output n lines (for i = 1 to n), each with m integers (for j = 1 to m)
    with open('/workdir/answer.txt', 'w') as f:
        for i in range(1, n + 1):
            row_vals = []
            for j in range(1, m + 1):
                row_vals.append(str(diff[i][j]))
            f.write(' '.join(row_vals) + '\n')

if __name__ == "__main__":
    solve()
